         Thread thread = Thread.currentThread();
         if (thread instanceof FortressTaskRunner) {
             FortressTaskRunner ftr = (FortressTaskRunner) thread;
             BaseTask saved = ftr.task();
             try {
                 this.join();
             } finally {
                 ftr.setTask(saved);
             }
         } else {
             this.join();
